/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# Baseline Jacobi-2D kernel operating on interior points only.
@proc
def kernel_jacobi_2d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
    B: DATA_TYPE[n, n] @ DRAM,
):
    # We update only interior points [1 : n-1), so n must be > 2.
    assert n > 2

    for t in seq(0, tsteps):
        # ------------------------------------------------------------------
        # Sweep 1: update B from A.
        # ------------------------------------------------------------------
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                # Use a local accumulator to make the stencil computation
                # explicit and encourage the compiler to keep values in
                # registers rather than reloading from memory.
                tmp: DATA_TYPE
                tmp = (
                    A[i, j]
                    + A[i, j - 1]
                    + A[i, j + 1]
                    + A[i + 1, j]
                    + A[i - 1, j]
                )
                B[i, j] = 0.2 * tmp

        # ------------------------------------------------------------------
        # Sweep 2: update A from B.
        # ------------------------------------------------------------------
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                tmp2: DATA_TYPE
                tmp2 = (
                    B[i, j]
                    + B[i, j - 1]
                    + B[i, j + 1]
                    + B[i + 1, j]
                    + B[i - 1, j]
                )
                A[i, j] = 0.2 * tmp2


# ======================================================================
# Scheduling / Optimization
#
# We apply spatial tiling to the (i, j) loops in both sweeps to improve
# cache locality, and parallelize the outer tile loops with OpenMP to
# exploit multicore CPUs. The tile sizes Ti and Tj can be tuned to a
# particular machine's cache hierarchy.
# ======================================================================

p = kernel_jacobi_2d

# Tunable tile sizes for the spatial loops.
Ti = 32
Tj = 32

# -------------------------
# Tile the B <- A sweep
# -------------------------

# The first 'i' loop encountered belongs to the B update.
i_B = p.find_loop("i")
p = divide_loop(p, i_B, Ti, ("io0", "ii0"), tail="guard")

# After tiling 'i', the first remaining 'j' loop is the inner loop of
# the B update. Tile it as well.
j_B = p.find_loop("j")
p = divide_loop(p, j_B, Tj, ("jo0", "ji0"), tail="guard")

# Reorder loops so that we iterate tiles first, then rows within a tile,
# and finally columns within a row:
#   for t
#     for io0    # tile over i
#       for jo0  # tile over j
#         for ii0
#           for ji0
p = reorder_loops(p, "ii0 jo0")

# Parallelize the outer i-tile loop of the first sweep.
p = parallelize_loop(p, p.find_loop("io0"))

# -------------------------
# Tile the A <- B sweep
# -------------------------

# After transforming the first sweep, the remaining 'i' loop refers to
# the second sweep (A update).
i_A = p.find_loop("i")
p = divide_loop(p, i_A, Ti, ("io1", "ii1"), tail="guard")

# And similarly for its inner 'j' loop.
j_A = p.find_loop("j")
p = divide_loop(p, j_A, Tj, ("jo1", "ji1"), tail="guard")

# Reorder as before: tiles over (i, j) outermost, then intra-tile loops
# with the column loop innermost for unit-stride access.
p = reorder_loops(p, "ii1 jo1")

# Parallelize the outer i-tile loop of the second sweep.
p = parallelize_loop(p, p.find_loop("io1"))

# Replace the original definition with the optimized version so that
# code generation uses the scheduled kernel.
kernel_jacobi_2d = p
