		 DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      {
	A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
	B[i][j] = ((DATA_TYPE) i*(j+3) + 3) / n;
      }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *

# Tunable unrolling factor for the inner j loop. This controls how many
# consecutive columns are processed per iteration after scheduling.
UNROLL_J = 4


@proc
def kernel_jacobi_2d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
    B: DATA_TYPE[n, n] @ DRAM,
):
    # We update only interior points [1 : n-1), so n must be > 2.
    assert n > 2

    for t in seq(0, tsteps):
        # Update B from A.
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                # 5-point Jacobi stencil on A into B.
                B[i, j] = 0.2 * (
                    A[i, j]
                    + A[i, j - 1]
                    + A[i, j + 1]
                    + A[i + 1, j]
                    + A[i - 1, j]
                )

        # Update A from B.
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                # Same stencil, now reading from B and writing back to A.
                A[i, j] = 0.2 * (
                    B[i, j]
                    + B[i, j - 1]
                    + B[i, j + 1]
                    + B[i + 1, j]
                    + B[i - 1, j]
                )


# Keep a handle to the unscheduled version for potential debugging or
# equivalence checking.
kernel_jacobi_2d_base = kernel_jacobi_2d

# Apply performance-oriented scheduling transformations.
s = kernel_jacobi_2d

# 1) Parallelize the row loops (i) in both sweeps.
#    Each iteration over i writes a distinct row and only reads from
#    neighboring rows, so iterations are independent and can be run in
#    parallel. This will generate OpenMP parallel for directives.
s = parallelize_loop(s, "i")      # first i-loop: B update
s = parallelize_loop(s, "i #1")   # second i-loop: A update

# 2) Tile and unroll the inner j loops to improve locality and enable
#    better vectorization. We split j into an outer (block) and inner
#    (within-block) loop with constant extent UNROLL_J, then fully unroll
#    the inner loop. A tail loop handles any remaining columns safely.
#
#    First apply this to the B update:
s = divide_loop(s, "j", UNROLL_J, ("j_outer_B", "j_inner_B"),
                tail="cut_and_guard")
s = unroll_loop(s, "j_inner_B")

#    Then apply the same transformation to the A update:
s = divide_loop(s, "j", UNROLL_J, ("j_outer_A", "j_inner_A"),
                tail="cut_and_guard")
s = unroll_loop(s, "j_inner_A")

# 3) Simplify the resulting code to clean up bounds expressions and any
#    guards introduced by the loop-division step.
s = simplify(s)

# Expose the optimized version under the original name used by the C driver.
kernel_jacobi_2d = s
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_jacobi_2d(/*ctxt=*/NULL,
                   tsteps, n,
                   (DATA_TYPE*)POLYBENCH_ARRAY(A),
                   (DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
